def synthetic_data(w, b, num_examples):  #@save
    """生成y=Xw+b+噪声"""
    X = native.normal(0, 1, (num_examples, len(w)))
    y = native.matmul(X, w) + b
    y += native.normal(0, 0.01, y.shape)
    return X, native.reshape(y, (-1, 1))

