def squared_loss(y_hat, y):  #@save
    """均方损失"""
    return (y_hat - native.reshape(y, y_hat.shape)) ** 2 / 2

# From chapter_03_linear_networks/linear_regression_scratch.py
def sgd(params, lr, batch_size):  #@save
    """小批量随机梯度下降"""
    with torch.no_grad():
        for param in params:
            param -= lr * param.grad / batch_size
            param.grad.zero_()

